import OmiTheme
import SwiftUI

/// Renders the most recent projection: one generated image carrying one imperative.
///
/// This is the spike surface for Omi's first non-chat-box output. Layout is deliberately
/// plain — the point is that the image and the line are real, generated by the backend and
/// read over the authenticated API.
struct ProjectionPage: View {
  @StateObject private var viewModel = ProjectionViewModel()

  private let contentMaxWidth: CGFloat = 520
  private let imageMaxHeight: CGFloat = 420

  var body: some View {
    ScrollView {
      VStack(spacing: 20) {
        content
        Button(action: { Task { await viewModel.generate() } }) {
          Text(viewModel.isGenerating ? "Generating…" : "Generate")
        }
        .disabled(viewModel.isGenerating)
      }
      .frame(maxWidth: contentMaxWidth)
      .frame(maxWidth: .infinity)
      .padding(.horizontal, 28)
      .padding(.vertical, 32)
    }
    .background(OmiColors.backgroundPrimary)
    .task { await viewModel.load() }
  }

  @ViewBuilder
  private var content: some View {
    if let projection = viewModel.projection {
      VStack(alignment: .leading, spacing: 16) {
        projectionImage(projection)
        Text(projection.imperative)
          .font(.system(size: 20, weight: .semibold))
          .fixedSize(horizontal: false, vertical: true)
      }
    } else if viewModel.isLoading {
      ProgressView()
        .frame(maxWidth: .infinity, minHeight: 240)
    } else {
      Text(viewModel.errorMessage ?? "No projection yet.")
        .frame(maxWidth: .infinity, minHeight: 240)
    }
  }

  @ViewBuilder
  private func projectionImage(_ projection: Projection) -> some View {
    if let url = projection.imageURL {
      AsyncImage(url: url) { phase in
        switch phase {
        case .success(let image):
          // Bounded so the imperative stays on screen: the generated image is 1024x1536,
          // and unbounded it pushes the line it exists to deliver below the fold.
          image.resizable().scaledToFit().frame(maxHeight: imageMaxHeight)
        case .failure:
          placeholder(systemName: "exclamationmark.triangle")
        default:
          ProgressView()
            .frame(maxWidth: .infinity, minHeight: 240)
            .background(OmiColors.backgroundTertiary.opacity(0.5))
        }
      }
      .clipShape(RoundedRectangle(cornerRadius: 12))
    } else {
      placeholder(systemName: "photo")
    }
  }

  private func placeholder(systemName: String) -> some View {
    ZStack {
      OmiColors.backgroundTertiary.opacity(0.6)
      Image(systemName: systemName)
    }
    .frame(maxWidth: .infinity, minHeight: 240)
    .clipShape(RoundedRectangle(cornerRadius: 12))
  }
}

@MainActor
final class ProjectionViewModel: ObservableObject {
  @Published private(set) var projection: Projection?
  @Published private(set) var isLoading = false
  @Published private(set) var isGenerating = false
  @Published private(set) var errorMessage: String?

  func load() async {
    isLoading = true
    defer { isLoading = false }
    do {
      projection = try await APIClient.shared.getProjections(limit: 1).first
      errorMessage = nil
    } catch {
      errorMessage = "Could not load projections: \(error.localizedDescription)"
    }
  }

  func generate() async {
    isGenerating = true
    defer { isGenerating = false }
    do {
      projection = try await APIClient.shared.generateProjection()
      errorMessage = nil
    } catch {
      errorMessage = "Could not generate a projection: \(error.localizedDescription)"
    }
  }
}
